sys_variable_value.value:
(function execute(inputs, outputs) {
    
    var input_table = inputs.table;
    var input_conditions = inputs.conditions.toString();
    var input_field = inputs.field;

    var ag = new GlideAggregate(input_table);
    ag.addEncodedQuery(input_conditions);
    ag.setGroup(false);
    ag.addAggregate('COUNT', input_field);
    ag.addAggregate('SUM', input_field);
    ag.addAggregate('AVG', input_field);
    ag.addAggregate('MIN', input_field);
    ag.addAggregate('MAX', input_field);
    ag.addAggregate('STDDEV', input_field);
    ag.query();

    if (ag.next()) {
        outputs.count = ag.getAggregate('COUNT', input_field);
        outputs.sum = ag.getAggregate('SUM', input_field);
        outputs.avg = (Number(ag.getAggregate('AVG', input_field) *100/100));
        outputs.min = ag.getAggregate('MIN', input_field);
        outputs.max = ag.getAggregate('MAX', input_field);
        outputs.stddev = ag.getAggregate('STDDEV', input_field);
        
    }

})(inputs, outputs);

